    size_t old_orbit=reverse_bucket_orbit_bytes(rb),new_orbit=split.bytes();std::cout<<"bucket-reverse-split18-selftest OK W="<<W<<" old_orbit_mib="<<double(old_orbit)/double(1<<20)<<" split_orbit_mib="<<double(new_orbit)/double(1<<20)<<" kind_bits=0 jblock_bits=0 bytes_per_orbit_payload=9 pm_accum="<<GPU_DIRECT_PM_ACCUM<<"\n";st.release();ct.release();dt.release();return 0;
